from bioblend.galaxy import GalaxyInstance
import os,json
url=os.environ.get('GALAXY_URL','https://usegalaxy.org')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
gi=GalaxyInstance(url=url,key=key)
tool=gi.tools.show_tool('toolshed.g2.bx.psu.edu/repos/goeckslab/phykit_metrics/phykit_metrics/0.2.0+galaxy0', io_details=True)
# Print compact conditional tree: labels, names, values, params for relevant operation values containing parsimony, alignment, pis maybe

def walk(inputs, indent=0):
    for inp in inputs or []:
        typ=inp.get('type'); name=inp.get('name')
        print('  '*indent + f\"{typ} {name} label={inp.get('label')"'!r} value={inp.get('"'value')"'!r} exts={inp.get('"'extensions')}\")
        if typ=='select':
            print('  '*indent+' options='+repr(inp.get('options'))[:1000])
        if typ=='conditional':
            tp=inp.get('test_param') or {}
            print('  '*indent+f\" test_param {tp.get('name')} value={tp.get('value')} options={tp.get('options')}\")
            for case in inp.get('cases') or []:
                val=case.get('value')
                if indent<1 or val in ['parsimony_informative_sites','alignment_length','collection','zip_archive','single']:
                    print('  '*indent+f\" CASE {val}\")
                    walk(case.get('inputs'), indent+1)
        if typ=='repeat':
            walk(inp.get('inputs'), indent+1)
walk(tool.get('inputs'))
PY"
